#!/usr/bin/env python3
"""Generate FULL_CHANGELOG.md from all BetterHvNote and NoteLink release tags."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from changelog_common import (
    CommitRecord,
    default_repo_root,
    format_category_counts_text,
    format_release_markdown,
    get_all_valid_release_tags,
    get_clean_tag_highlights,
    get_commits_in_range,
    get_release_tag_record,
    github_anchor_slug,
    is_commit_relevant_to_product,
    resolve_github_repo_slug,
    resolve_previous_release_links,
    write_utf8_lf,
)


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Generate FULL_CHANGELOG.md from product release tags.")
    parser.add_argument(
        "--tags",
        nargs="*",
        help="Optional explicit list of release tags (defaults to all valid note-v* and notelink-v* git tags)",
    )
    parser.add_argument("--repo-path", default=str(default_repo_root()), help="Path to the git repository")
    parser.add_argument("--repo-slug", help="GitHub owner/repo slug for links (auto-detected from origin if omitted)")
    parser.add_argument("--output", default="FULL_CHANGELOG.md", help="Output path (default: FULL_CHANGELOG.md)")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    repo_path = Path(args.repo_path).resolve()
    repo_slug = resolve_github_repo_slug(repo_path, args.repo_slug)

    resolved_tags = list(args.tags) if args.tags else get_all_valid_release_tags(repo_path)
    if not resolved_tags:
        raise ValueError("At least one release tag is required.")

    seen_tags: set[str] = set()
    records = []
    for tag in resolved_tags:
        if tag in seen_tags:
            raise ValueError(f"Release tag '{tag}' was supplied more than once.")
        seen_tags.add(tag)
        records.append(get_release_tag_record(repo_path, tag))

    resolve_previous_release_links(repo_path, records)

    # Sort newest first: CreatedAt descending, ProductName ascending, SemVer descending.
    ordered_records = sorted(
        records,
        key=lambda r: (-r.created_at, r.product_name, (-r.semver[0], -r.semver[1], -r.semver[2])),
    )

    commits_by_tag: dict[str, list[CommitRecord]] = {}
    for record in ordered_records:
        commits_by_tag[record.tag] = get_commits_in_range(repo_path, record.previous_commit, record.commit)

    parts: list[str] = [
        "<!-- Generated by .github/scripts/generate_full_changelog.py. Do not edit manually. -->\n\n",
        "# Changelog\n\n",
        (
            "Release history for **BetterHvNote** (`note-v*`) and **NoteLink** (`notelink-v*`). "
            "Each entry lists only the incremental changes relevant to that product since its previous release.\n\n"
        ),
        "## Release Index\n\n",
        "| Product | Version | Tag | Date | Since | Summary |\n",
        "| --- | --- | --- | --- | --- | --- |\n",
    ]

    for record in ordered_records:
        heading = f"{record.product_name} {record.version}"
        anchor = github_anchor_slug(heading)
        relevant = [c for c in commits_by_tag[record.tag] if is_commit_relevant_to_product(c, record.product)]
        highlights = get_clean_tag_highlights(record)
        if highlights.headline:
            summary = highlights.headline
        else:
            summary = format_category_counts_text(relevant).replace("**", "")
        summary = summary.replace("|", "\\|")
        since_cell = f"`{record.previous_tag}`" if record.previous_tag else "Initial"
        parts.append(
            f"| {record.product_name} | [{record.version}](#{anchor}) | `{record.tag}` | "
            f"{record.release_date} | {since_cell} | {summary} |\n"
        )

    parts.append("\n")

    for record in ordered_records:
        section = format_release_markdown(
            record,
            commits_by_tag[record.tag],
            repo_slug=repo_slug,
            mode="full_changelog",
        )
        parts.append("---\n\n")
        parts.append(section)
        parts.append("\n")

    output_path = Path(args.output)
    if not output_path.is_absolute():
        output_path = repo_path / output_path
    resolved_output = write_utf8_lf(output_path, "".join(parts).rstrip() + "\n")
    print(resolved_output)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as error:
        print(f"ERROR: {error}", file=sys.stderr)
        raise SystemExit(1)
